void charts(){card("Study rhythm · last 7 days","Hours logged per day · no data is filled in for you");View chart=new View(this){Paint p=new Paint(3);protected void onDraw(Canvas c){super.onDraw(c);float w=getWidth(),h=getHeight();JSONArray a=arr(data.optJSONObject("records"),"daily");float[] vals=new float[7];String[] days=new String[7];Calendar now=Calendar.getInstance();for(int i=6;i>=0;i--){Calendar d=(Calendar)now.clone();d.add(Calendar.DAY_OF_YEAR,-i);String date=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(d.getTime());days[6-i]=new java.text.SimpleDateFormat("EE",Locale.US).format(d.getTime());for(int j=0;j<a.length();j++){JSONObject x=a.optJSONObject(j);if(date.equals(x.optString("Date")))vals[6-i]+=((float)num(x,"Duration (min)"))/60f;}}float max=1;for(float v:vals)max=Math.max(max,v);float base=h-dp(24),gap=dp(10),bw=(w-gap*8)/7;p.setColor(0xff30384a);c.drawLine(0,base,w,base,p);for(int i=0;i<7;i++){float left=gap+i*(bw+gap),bh=(base-dp(12))*vals[i]/max;p.setColor(CYAN);c.drawRoundRect(left,base-bh,left+bw,base,dp(5),dp(5),p);p.setColor(MUTED);p.setTextSize(dp(9));c.drawText(days[i],left, h-dp(5),p);}}};lastCard().addView(chart,new LinearLayout.LayoutParams(-1,dp(116)));card("Accuracy by subject","Correct answers ÷ attempted questions");for(String subject:subjects){JSONArray q=arr(data.optJSONObject("records"),"questions");double at=0,co=0;for(int i=0;i<q.length();i++){JSONObject x=q.optJSONObject(i);if(subject.equals(x.optString("Subject"))){at+=num(x,"Attempted");co+=num(x,"Correct");}}LinearLayout line=new LinearLayout(this);line.setGravity(Gravity.CENTER_VERTICAL);TextView name=txt(subject,12,FG,true);line.addView(name,new LinearLayout.LayoutParams(dp(112),-2));ProgressBar bar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);bar.setProgress(at==0?0:(int)Math.round(co/at*100));bar.setProgressTintList(android.content.res.ColorStateList.valueOf(subject.equals("Physics")?CYAN:subject.equals("Chemistry")?BLUE:0xffd08cff));bar.setProgressBackgroundTintList(android.content.res.ColorStateList.valueOf(0xff30384a));line.addView(bar,new LinearLayout.LayoutParams(0,dp(8),1));TextView pct=txt(at==0?"—":Math.round(co/at*100)+"%",11,MUTED,true);pct.setGravity(Gravity.RIGHT);line.addView(pct,new LinearLayout.LayoutParams(dp(46),-2));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(32));lastCard().addView(line,lp);}}void chapterPage(){heading("Chapter Master","Enter actual mock marks. Weak chapters sort to the top.");card("Star scale","<20: 0★  ·  20–39: 1★  ·  40–59: 2★  ·  60–79: 3★  ·  80–99: 4★  ·  100: 5★");addButton("＋  Add chapter",()->edit("Chapter Master",null));JSONArray a=arr(data,"master");ArrayList<JSONObject> list=new ArrayList<>();for(int i=0;i<a.length();i++)list.add(a.optJSONObject(i));list.sort(Comparator.comparingDouble(c->c.optString("mockMarks").isEmpty()?100:num(c,"mockMarks")));for(JSONObject c:list)item(c.optString("chapter"),c.optString("subject")+" · "+(c.optString("mockMarks").isEmpty()?"Not rated":starText(num(c,"mockMarks"))+" · "+fmt((int)num(c,"mockMarks"))+"/100")+" · "+c.optString("status","Not Started"),()->edit("Chapter Master",c),()->delete("master",c));}
