String[][] fields(String p){switch(p){case "Chapter Master":return new String[][]{{"Subject","subject"},{"Chapter","text"},{"Syllabus list","text"},{"Status","status"},{"Confidence","confidence"},{"Recent mock mark / 100","number"},{"Notes","textarea"}};case "Daily Study Log":return new String[][]{{"Date","date"},{"Subject","subject"},{"Chapter","chapter"},{"Study type","studytype"},{"Duration (min)","number"},{"Notes","textarea"}};case "Question Bank Log":return new String[][]{{"Date","date"},{"Subject","subject"},{"Chapter","chapter"},{"Difficulty","difficulty"},{"Source / set","text"},{"Attempted","number"},{"Correct","number"},{"Time (min)","number"},{"Notes","textarea"}};case "Mock Test Analytics":return new String[][]{{"Date","date"},{"Exam","exam"},{"Test name","text"},{"Physics score","number"},{"Physics max","number"},{"Chemistry score","number"},{"Chemistry max","number"},{"Mathematics score","number"},{"Mathematics max","number"},{"Total score","number"},{"Total max","number"},{"Duration (min)","number"},{"Notes","textarea"}};case "Mistake Register":return new String[][]{{"Date","date"},{"Mock test","mockref"},{"Subject","subject"},{"Chapter","chapter"},{"Mistake type","mistaketype"},{"Question / source","text"},{"What went wrong","textarea"},{"Correct approach","textarea"},{"Resolved?","yesno"}};case "Revision Scheduler":return new String[][]{{"Due date","date"},{"Subject","subject"},{"Chapter","chapter"},{"Revision number","number"},{"Status","revisionstatus"},{"Completed date","date"},{"Notes","textarea"}};default:return new String[][]{{"Week starting","date"},{"Subject","subject"},{"Target type","targettype"},{"Target value","number"},{"Actual value","number"},{"Notes","textarea"}};}}
String[] choices(String t){switch(t){case "subject":return subjects;case "exam":return new String[]{"JEE Main","JEE Advanced"};case "status":case "revisionstatus":return new String[]{"Not Started","In Progress","Completed"};case "confidence":return new String[]{"Low","Medium","High"};case "difficulty":return new String[]{"Easy","Moderate","Hard"};case "studytype":return new String[]{"Concept Study","Problem Practice","Revision","Mock Analysis"};case "mistaketype":return new String[]{"Conceptual","Calculation","Misread","Time Management","Guessing","Test Strategy"};case "yesno":return new String[]{"No","Yes"};case "targettype":return new String[]{"Study Hours","Questions Attempted"};default:return null;}}
void edit(String p,JSONObject current){boolean chapter=p.equals("Chapter Master");String[][] fs=fields(p);LinearLayout form=new LinearLayout(this);form.setPadding(dp(15),dp(5),dp(15),dp(4));form.setOrientation(1);ScrollView sc=new ScrollView(this);sc.addView(form);ArrayList<String> names=new ArrayList<>();ArrayList<View> inputs=new ArrayList<>();for(String[] f:fs){String name=f[0],type=f[1],key=chapter?chapterKey(name):name;TextView lab=txt(name.toUpperCase(Locale.ROOT),9,MUTED,true);lab.setPadding(0,dp(7),0,dp(3));form.addView(lab);String value=current==null?"":current.optString(key,"");View in;if(type.equals("mockref")){String[] opts=mockOptions();Spinner sp=spinner(opts);for(int i=1;i<opts.length;i++)if(opts[i].startsWith(value+"|"))sp.setSelection(i);in=sp;}else{String[] opts=choices(type);if(opts!=null){Spinner sp=spinner(opts);for(int i=0;i<opts.length;i++)if(opts[i].equals(value))sp.setSelection(i);in=sp;}else{EditText e=new EditText(this);e.setText(value);e.setTextColor(FG);e.setHintTextColor(MUTED);e.setTextSize(13);e.setHint(name);e.setSingleLine(!type.equals("textarea"));e.setPadding(dp(10),dp(6),dp(10),dp(6));e.setBackground(shape(0xff0e1119,0xff30394a,10));if(type.equals("number"))e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);if(type.equals("textarea")){e.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_FLAG_MULTI_LINE);e.setMinLines(2);}if(type.equals("date")&&value.isEmpty())e.setText(today());in=e;}}form.addView(in,new LinearLayout.LayoutParams(-1,dp(type.equals("textarea")?70:43)));names.add(name);inputs.add(in);}
AlertDialog dlg=new AlertDialog.Builder(this).setTitle((current==null?"Add ":"Edit ")+p).setView(sc).setNegativeButton("Cancel",null).setPositiveButton("Save",null).create();dlg.setOnShowListener(v->dlg.getButton(-1).setOnClickListener(b->{try{JSONObject out=current==null?new JSONObject():current;for(int i=0;i<names.size();i++){String n=names.get(i),val;View x=inputs.get(i);if(x instanceof Spinner){val=((Spinner)x).getSelectedItem().toString();if(n.equals("Mock test")){if(val.equals("No mock linked"))val="";else val=val.substring(0,val.indexOf('|'));}}else val=((EditText)x).getText().toString().trim();out.put(chapter?chapterKey(n):n,val);}if(chapter&&out.optString("Chapter").trim().isEmpty()){toast("Add a chapter name first.");return;}if(chapter&&!out.optString("mockMarks").isEmpty()&&(num(out,"mockMarks")<0||num(out,"mockMarks")>100)){toast("Marks must be between 0 and 100.");return;}if(p.equals("Question Bank Log")&&num(out,"Correct")>num(out,"Attempted")){toast("Correct cannot exceed attempted.");return;}if(current==null)out.put("id",UUID.randomUUID().toString());if(p.equals("Mistake Register"))out.put("Mock test label",mockName(out.optString("Mock test")));if(current==null)arrayFor(chapter?"master":keyOf(p)).put(out);persist();dlg.dismiss();render();}catch(Exception e){toast("Could not save this entry.");}}));dlg.show();dlg.getWindow().setLayout((int)(getResources().getDisplayMetrics().widthPixels*.92),dp(590));dlg.getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);}
Spinner spinner(String[] opts){Spinner s=new Spinner(this);ArrayAdapter<String>a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,opts);s.setAdapter(a);s.setBackground(shape(0xff0e1119,0xff30394a,10));return s;}
