void mockMenu(JSONObject m){new AlertDialog.Builder(this).setTitle(m.optString("Test name","Mock test")).setItems(new String[]{"Edit mock","Linked mistakes"},(d,n)->{if(n==0)edit("Mock Test Analytics",m);else{JSONArray a=arr(data.optJSONObject("records"),"mistakes");StringBuilder s=new StringBuilder();for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x.optString("Mock test").equals(m.optString("id")))s.append("• ").append(x.optString("Chapter")).append(" · ").append(x.optString("Mistake type")).append("\n");}new AlertDialog.Builder(this).setTitle("Mistakes linked to this mock").setMessage(s.length()==0?"No linked mistakes yet.":s.toString()).setPositiveButton("Done",null).show();}}).show();}
